window.NESS_API = {
  user:null,
  permissions:[],
  liveSocket:null,
  liveReconnectTimer:null,
  livePaused:false,
  liveSyncTimer:null,
  lastUiRevision:null,
  refreshBusy:false,
  async request(path, options={}){
    const res = await fetch(path, {credentials:'same-origin', headers:{'Content-Type':'application/json'}, ...options});
    const contentType = res.headers.get('content-type') || '';
    const data = contentType.includes('application/json') ? await res.json().catch(()=>({ok:false,error:'Invalid server response'})) : {ok:res.ok};
    if(res.status===401){ if(document.body.classList.contains('app-body')) location.href='login.html'; throw new Error('Authentication required'); }
    if(res.status===403){ location.href='access-denied.html'; throw new Error('Access denied'); }
    if(!res.ok || data.ok===false) throw new Error(data.error || `Request failed: ${res.status}`);
    return data;
  },
  async get(path){return this.request(path)},
  async post(path, body={}){return this.request(path,{method:'POST',body:JSON.stringify(body)})},
  async put(path, body={}){return this.request(path,{method:'PUT',body:JSON.stringify(body)})},
  async boot(){ this.bindLogin(); this.bindAuthUtilityForms(); if(document.body.classList.contains('app-body')){ await this.loadEverything(false); this.startRealtimeAlerts(); this.startLiveDataSync(); } },
  async loadEverything(force=false){ await this.loadCurrentUser(); await this.loadUiData(force); await this.loadDashboardSummary(); await this.loadSettings(); await this.loadDetailsPage(); this.bindLiveButtons(); },
  async bindLogin(){ const form=document.querySelector('body[data-page="login.html"] form.auth-form'); if(!form) return; let setup=false; try{ const st=await this.get('/api/setup/status'); setup=!!st.needsSetup; }catch(e){} if(setup){ const title=document.querySelector('h1'); const desc=document.querySelector('.auth-panel p'); if(title) title.textContent='Initial Administrator Setup'; if(desc) desc.textContent='Create the first Administrator account. No sample credentials are shipped with the project.'; const fields=form.querySelectorAll('.field'); if(fields[0]) fields[0].innerHTML='<label>Full Name</label><input class="input" type="text" required>'; if(fields[1]) fields[1].innerHTML='<label>Email</label><input class="input" type="email" required>'; form.insertBefore(Object.assign(document.createElement('div'),{className:'field',innerHTML:'<label>Username</label><input class="input" type="text" required>'}), form.querySelector('.toolbar')); form.insertBefore(Object.assign(document.createElement('div'),{className:'field',innerHTML:'<label>Password</label><input class="input" type="password" minlength="8" required>'}), form.querySelector('.toolbar')); const toolbar=form.querySelector('.toolbar'); if(toolbar) toolbar.remove(); const btn=form.querySelector('button[type="submit"]'); if(btn) btn.innerHTML='<i class="fa-solid fa-user-shield"></i> Create Administrator'; } form.addEventListener('submit',async e=>{ e.preventDefault(); const inputs=form.querySelectorAll('input'); try{ if(setup){ await this.post('/api/setup/initial-admin',{name:inputs[0]?.value||'',email:inputs[1]?.value||'',username:inputs[2]?.value||'',password:inputs[3]?.value||''}); NESS.toast('Initial Administrator created','success'); setTimeout(()=>location.href='dashboard.html',350); return; } const email=inputs[0]?.value||''; const password=inputs[1]?.value||''; const res=await this.post('/api/auth/login',{email,password}); if(res.requires2FA){ sessionStorage.setItem('ness_2fa_code',res.verificationCode||''); NESS.toast('Two-factor verification required','info'); setTimeout(()=>location.href='two-factor.html',350); return; } NESS.toast('Logged in successfully','success'); setTimeout(()=>location.href='dashboard.html',350); }catch(err){ NESS.toast(err.message,'danger'); } }); },
  bindAuthUtilityForms(){ const page=document.body.dataset.page; if(page==='forgot-password.html'){ const form=document.querySelector('form.auth-form'); form?.addEventListener('submit',async e=>{ e.preventDefault(); const email=form.querySelector('input')?.value||''; try{ const r=await this.post('/api/auth/forgot-password',{email}); NESS.toast(r.resetToken?'Reset token generated for this local deployment':'If the account exists, reset instructions were generated','success'); if(r.resetUrl) setTimeout(()=>location.href=r.resetUrl,450); }catch(err){ NESS.toast(err.message,'danger'); } }); } if(page==='reset-password.html'){ const form=document.querySelector('form.auth-form'); form?.addEventListener('submit',async e=>{ e.preventDefault(); const inp=form.querySelectorAll('input'); const password=inp[0]?.value||''; const confirm=inp[1]?.value||''; if(password!==confirm){NESS.toast('Passwords do not match','danger');return;} const token=new URLSearchParams(location.search).get('token')||''; try{ await this.post('/api/auth/reset-password',{token,password}); NESS.toast('Password reset successfully','success'); setTimeout(()=>location.href='login.html',450); }catch(err){ NESS.toast(err.message,'danger'); } }); } if(page==='two-factor.html'){ const code=sessionStorage.getItem('ness_2fa_code'); if(code){ [...document.querySelectorAll('.pin-row input')].forEach((el,i)=>el.placeholder=code[i]||''); } const form=document.querySelector('form.auth-form'); form?.addEventListener('submit',async e=>{ e.preventDefault(); const code=[...document.querySelectorAll('.pin-row input')].map(x=>x.value).join(''); try{ await this.post('/api/auth/verify-2fa',{code}); NESS.toast('Verification completed','success'); setTimeout(()=>location.href='dashboard.html',350); }catch(err){ NESS.toast(err.message,'danger'); } }); } if(page==='lock-screen.html'){ const form=document.querySelector('form.auth-form'); form?.addEventListener('submit',async e=>{ e.preventDefault(); try{ await this.post('/api/auth/unlock',{password:form.querySelector('input[type="password"]')?.value||''}); NESS.toast('Session unlocked','success'); setTimeout(()=>location.href='dashboard.html',350); }catch(err){ NESS.toast(err.message,'danger'); } }); } const pwdBtn=document.querySelector('body[data-page="change-password.html"] .button-primary'); if(pwdBtn){ pwdBtn.addEventListener('click',async e=>{ e.preventDefault(); const inputs=[...document.querySelectorAll('input')]; try{ await this.post('/api/profile/password',{current_password:inputs[0]?.value||'',new_password:inputs[1]?.value||''}); NESS.toast('Password updated in the database','success'); }catch(err){ NESS.toast(err.message,'danger'); } }); } },
  async loadCurrentUser(){ try{ const data=await this.get('/api/me'); this.user=data.user; this.permissions=data.permissions||[]; const initials=(this.user.name||'NA').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(); document.querySelectorAll('.role-pill').forEach(el=>el.innerHTML=`<i class="fa-solid fa-id-badge"></i> ${NESS.escape(this.user.role)}`); document.querySelectorAll('.operator-card strong').forEach(el=>el.textContent=this.user.name); document.querySelectorAll('.operator-card small').forEach(el=>el.textContent=this.user.role); document.querySelectorAll('.operator-card .avatar').forEach(el=>el.textContent=initials); this.applyRoleVisibility(); }catch(e){ if(document.body.classList.contains('app-body')) location.href='login.html'; } },
  can(permission){ return (this.permissions||[]).includes('*') || (this.permissions||[]).includes(permission); },
  applyRoleVisibility(){ if(!this.user) return; const adminPages={
      'users.html':'user_manage',
      'roles-permissions.html':'permissions_manage',
      'settings.html':'settings_read'
    }; document.querySelectorAll('.nav-link').forEach(a=>{ const href=a.getAttribute('href')||''; const required=adminPages[href]; if(required && !this.can(required)) a.classList.add('disabled-nav'); else a.classList.remove('disabled-nav'); }); },
  async loadUiData(force=false){ try{ const data=await this.get('/api/ui-data'); Object.assign(window.NESS_DATA,data); delete window.NESS_DATA.ok; NESS.renderDataTables(true); this.renderEmptyHints(); this.updateDashboardLivePanels(); }catch(e){ console.warn(e); } },
  renderEmptyHints(){ document.querySelectorAll('table tbody').forEach(tbody=>{ if(tbody.children.length===0){ const cols=tbody.closest('table')?.querySelectorAll('thead th').length||1; tbody.innerHTML=`<tr><td colspan="${cols}" style="text-align:center;color:var(--muted);padding:26px">No database records are available for this page yet.</td></tr>`; } }); },
  async loadDashboardSummary(){ if(document.body.dataset.page!=='dashboard.html') return; try{ const {summary}=await this.get('/api/dashboard/summary'); const labelMatches=(txt,label)=>window.NESS_I18N?window.NESS_I18N.matches(txt,label):String(txt||'').toLowerCase().includes(label.toLowerCase()); const setMetric=(label,value)=>{ [...document.querySelectorAll('.metric-card')].forEach(card=>{ if(labelMatches(card.querySelector('.metric-label')?.textContent||'',label)){ const v=card.querySelector('.metric-value'); if(v) v.textContent=value; }});}; setMetric('Total Incidents',summary.totalIncidents); setMetric("Today's Attacks",summary.todaysAttacks); setMetric('Critical Alerts',summary.criticalAlerts); setMetric('Cyber Range Nodes',summary.cyberRangeNodes); setMetric('Online Network Devices',summary.networkDevicesOnline); setMetric('Network Flows 24h',summary.networkFlows24h); setMetric('Network Threats 24h',summary.networkThreats24h); setMetric('Network Sensor State',summary.networkSensor); const badge=document.querySelector('.notification-badge'); if(badge) badge.textContent=summary.unreviewedAlerts; [...document.querySelectorAll('.health-row')].forEach(row=>{const label=row.querySelector('span')?.textContent||row.textContent||''; const b=row.querySelector('.badge'); const is=(key)=>labelMatches(label,key); if(is('Telegram alerts')&&b) b.textContent=summary.telegramStatus; if(is('Arduino alarm')&&b) b.textContent=summary.arduinoStatus; if(is('Realtime engine')&&b) b.textContent=summary.automationStatus||'Unknown'; if(is('Automatic AI')&&b) b.textContent=summary.automaticAI||'Unknown'; if(is('Automatic log analysis')&&b) b.textContent=summary.automaticLogAnalysis||'Unknown'; if(is('Cyber Range')&&b) b.textContent=summary.networkDiscovery||'Unknown'; if(is('Lab device sync')&&b) b.textContent=(summary.networkDevicesOnline>0?'Running':'Waiting'); if(is('Gateway sensor')&&b){b.textContent=summary.networkSensor||'Unknown';b.className='badge '+(summary.networkSensor==='Running'?'badge-active':summary.networkSensor==='Degraded'?'badge-warning':'badge-muted');} if(is('System health')){const strong=row.querySelector('strong');if(strong)strong.textContent=summary.systemHealth||'Operational';}}); const progress=document.querySelector('.health-row')?.closest('.panel')?.querySelector('.progress span');if(progress)progress.style.width='100%'; }catch(e){console.warn(e)} },
  updateDashboardLivePanels(){ if(document.body.dataset.page!=='dashboard.html') return; const last=(window.NESS_DATA.incidents||[])[0]; const latestAI=(window.NESS_DATA.analysisHistory||[])[0]; const p=[...document.querySelectorAll('.panel-title')].find(x=>window.NESS_I18N?window.NESS_I18N.matches(x.textContent,'AI Insight'):x.textContent.includes('AI Insight'))?.closest('.panel')?.querySelector('.panel-body p'); if(p){ if(latestAI) p.innerHTML=`NESS analyzed <strong>${NESS.escape(latestAI.incident)}</strong> automatically in real time: <strong>${NESS.escape(latestAI.classification)}</strong>, risk <strong>${NESS.escape(latestAI.riskScore)}/100</strong>, predicted priority <strong>${NESS.escape(latestAI.predictedSeverity)}</strong>.`; else if(last) p.innerHTML=`Incident <strong>${NESS.escape(last.id)}</strong> was detected automatically and has been queued for real-time AI classification and prediction.`; else p.textContent='NESS is monitoring automatically in real time. New suspicious activity will be detected, classified, analyzed, scored, predicted, stored, and displayed without manual analysis.'; } const feed=document.getElementById('dashboardAlertsFeed');if(feed){const alerts=(window.NESS_DATA.alerts||[]).slice(0,4);feed.innerHTML=alerts.length?alerts.map(a=>`<div class="feed-item"><div class="feed-icon ${String(a.severity).toLowerCase()==='critical'?'icon-danger':'icon-warning'}"><i class="fa-solid fa-triangle-exclamation"></i></div><div><strong>${NESS.escape(a.incident||'Security Alert')} • ${NESS.escape(a.severity)}</strong><p>${NESS.escape(a.event)} • Arduino: ${NESS.escape(a.arduino)}</p></div></div>`).join(''):'<p style="color:var(--muted)">No alerts recorded yet.</p>';} },
  async loadDetailsPage(){ const page=document.body.dataset.page; if(page==='incident-details.html') return this.renderIncidentDetails(); if(page==='evidence-details.html') return this.renderEvidenceDetails(); if(page==='report-preview.html') return this.renderReportPreview(); if(page==='ai-analysis.html') return this.renderAiPage(); if(page==='generate-report.html') return this.renderGenerateReportPage(); if(page==='settings.html') return this.renderSettingsPage(); if(page==='ints-tracking.html') return this.loadIntsTracking(); if(page==='logs.html') return this.loadLogAnalysisHistory(); if(page==='roles-permissions.html') return this.renderRolesPermissionsPage(); if(page==='profile.html') return this.renderProfilePage(false); if(page==='user-profile.html') return this.renderProfilePage(true); if(page==='alerts.html') return this.renderAlertSummary(); if(page==='network-devices.html') return this.loadNetworkDevicesPage(); if(page==='network-traffic.html') return this.loadNetworkTrafficPage(); if(page==='users.html') return this.bindUsersPage(); },
  params(){return new URLSearchParams(location.search)},
  async renderIncidentDetails(){ const id=this.params().get('id')||'latest'; const main=document.querySelector('main.page'); if(!main) return; try{ const data=await this.get(`/api/incidents/${encodeURIComponent(id)}`); const i=data.incident, ev=data.evidence||[], h=data.history||[], ints=data.ints||[], an=data.analysis; main.innerHTML=`<section class="page-header"><div><div class="breadcrumb">NESS Platform / Incidents / ${NESS.escape(i.incident_code)}</div><h1>${NESS.escape(i.incident_code)}</h1></div><div class="page-header-actions"><button class="button button-primary" onclick="NESS_API.quickStatus(${i.id},'Under Investigation')">Start Investigation</button><button class="button button-secondary" onclick="NESS_API.quickStatus(${i.id},'Resolved')">Mark Resolved</button></div></section><div class="grid grid-main"><div class="grid"><section class="panel"><div class="panel-header"><div><div class="panel-title">Incident Overview</div><div class="panel-subtitle">${NESS.escape(i.attack_type)} • ${NESS.escape(i.severity)}</div></div>${window.NESS_DATA.statusBadge(i.status)}</div><div class="panel-body"><div class="grid grid-3"><div class="card"><div class="metric-label">Target</div><strong>${NESS.escape(i.target||i.path||'')}</strong></div><div class="card"><div class="metric-label">Source IP</div><strong>${NESS.escape(i.source_ip)}</strong></div><div class="card"><div class="metric-label">Detected</div><strong>${NESS.escape(i.created_at)}</strong></div></div><div class="grid grid-3" style="margin-top:14px"><div class="card"><div class="metric-label">Method</div><strong>${NESS.escape(i.method||'')}</strong></div><div class="card"><div class="metric-label">Location</div><strong>${NESS.escape((i.source_country||'')+' '+(i.source_city||''))}</strong></div><div class="card"><div class="metric-label">Assigned To</div><strong>${NESS.escape(data.owner?.name||'Unassigned')}</strong></div></div></div></section><section class="panel"><div class="panel-header"><div class="panel-title">Captured Payload</div><button class="button button-secondary button-small" onclick="navigator.clipboard?.writeText(document.getElementById('payloadBox').innerText);NESS.toast('Payload copied','success')">Copy</button></div><div class="panel-body"><div class="log-viewer" id="payloadBox">${NESS.escape(i.payload||i.query_string||'No payload recorded')}</div></div></section><section class="panel"><div class="panel-header"><div class="panel-title">Raw Request Data</div></div><div class="panel-body"><div class="log-viewer">${window.NESS_I18N?.t('Method')||'Method'}: ${NESS.escape(i.method||'')}\n${window.NESS_I18N?.t('Path')||'Path'}: ${NESS.escape(i.path||'')}\n${window.NESS_I18N?.t('Query')||'Query'}: ${NESS.escape(i.query_string||'')}\n${window.NESS_I18N?.t('User-Agent')||'User-Agent'}: ${NESS.escape(i.user_agent||'')}\n${window.NESS_I18N?.t('Description')||'Description'}: ${NESS.escape(i.description||'')}</div></div></section><section class="panel"><div class="panel-header"><div class="panel-title">Digital Evidence</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Evidence ID</th><th>Type</th><th>Hash</th><th>Collected</th><th>Action</th></tr></thead><tbody>${ev.length?ev.map(e=>`<tr><td>${NESS.escape(e.evidence_code)}</td><td>${NESS.escape(e.evidence_type)}</td><td><code>${NESS.escape(e.hash_value.slice(0,18))}</code></td><td>${NESS.escape(e.captured_at)}</td><td><button class="button button-secondary button-small" onclick="location.href='evidence-details.html?id=${e.id}'">Open</button></td></tr>`).join(''):'<tr><td colspan="5">No evidence records.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-header"><div class="panel-title">Investigation Notes</div></div><div class="panel-body"><textarea id="incidentNotes" class="textarea">${NESS.escape(i.description||'')}</textarea><button class="button button-primary" style="margin-top:12px" onclick="NESS_API.saveIncidentNotes(${i.id})">Save notes</button></div></section></div><aside class="grid"><section class="panel"><div class="panel-header"><div><div class="panel-title">Automatic AI Analysis</div><div class="panel-subtitle">Generated automatically by the real-time engine</div></div></div><div class="panel-body">${an?`<div class="grid grid-2"><div><div class="metric-label">Classification</div><strong>${NESS.escape(an.classification||i.attack_type)}</strong></div><div><div class="metric-label">Risk / Predicted Priority</div><strong>${NESS.escape(an.risk_score??0)}/100 • ${NESS.escape(an.predicted_severity||i.severity)}</strong></div></div><p>${NESS.escape(an.analysis_summary)}</p><h4>Prediction</h4><p>${NESS.escape(an.prediction||'')}</p><h4>Recommendations</h4><pre class="log-viewer">${NESS.escape(an.recommendations)}</pre>`:'<p style="color:var(--muted)">Automatic AI analysis is queued and will appear here as soon as the real-time engine finishes classification and prediction.</p>'}<button class="button button-primary button-small" onclick="location.href='ai-analysis.html'">Open Live AI Console</button></div></section><section class="panel"><div class="panel-header"><div class="panel-title">INTS Tracking History</div></div><div class="panel-body"><div class="timeline">${ints.length?ints.map(x=>`<div class="timeline-item"><strong>${NESS.escape(x.event_type)} • ${NESS.escape(x.status||'Recorded')}</strong><p>${NESS.escape(x.created_at)} • ${NESS.escape(x.created_by_name||'NESS Engine')}</p><p>${NESS.escape(x.notes||'')}</p></div>`).join(''):'<p>No INTS events recorded.</p>'}</div><button class="button button-secondary button-small" onclick="location.href='ints-tracking.html'">Open Full INTS</button></div></section><section class="panel"><div class="panel-header"><div class="panel-title">Status Timeline</div></div><div class="panel-body"><div class="timeline">${h.length?h.map(x=>`<div class="timeline-item"><strong>${NESS.escape(x.new_status)}</strong><p>${NESS.escape(x.changed_at)} • ${NESS.escape(x.remarks||'')} • ${NESS.escape(x.changed_by_name||'NESS')}</p></div>`).join(''):'<p>No status history.</p>'}</div></div></section><section class="panel"><div class="panel-header"><div class="panel-title">Assignment</div></div><div class="panel-body"><select id="incidentAssignee" class="select">${(window.NESS_DATA.users||[]).map(u=>`<option value="${u.id}" ${data.owner?.id===u.id?'selected':''}>${NESS.escape(u.name)} — ${NESS.escape(u.role)}</option>`).join('')}</select><button class="button button-secondary button-block" style="margin-top:10px" onclick="NESS_API.assignIncident(${i.id})">Assign</button></div></section></aside></div>`; }catch(e){ main.innerHTML=`<section class="panel empty-state"><h2>Incident not found</h2><p>${NESS.escape(e.message)}</p></section>`; } },
  async renderEvidenceDetails(){ const id=this.params().get('id')||'latest'; const main=document.querySelector('main.page'); if(!main) return; try{ const {evidence:e}=await this.get(`/api/evidence/${encodeURIComponent(id)}`); main.innerHTML=`<section class="page-header"><div><div class="breadcrumb">NESS Platform / Evidence / ${NESS.escape(e.evidence_code)}</div><h1>Evidence Details</h1></div><button class="button button-secondary" onclick="location.href='incident-details.html?id=${e.incident_id}'">Open Incident</button></section><div class="grid grid-main"><section class="panel"><div class="panel-header"><div><div class="panel-title">${NESS.escape(e.evidence_code)}</div><div class="panel-subtitle">Linked to ${NESS.escape(e.incident_code)}</div></div><span class="badge badge-active">Preserved</span></div><div class="panel-body"><div class="grid grid-3"><div class="card"><div class="metric-label">Evidence Type</div><strong>${NESS.escape(e.evidence_type)}</strong></div><div class="card"><div class="metric-label">Source IP</div><strong>${NESS.escape(e.source_ip)}</strong></div><div class="card"><div class="metric-label">Captured</div><strong>${NESS.escape(e.captured_at)}</strong></div></div><h3>SHA256 Integrity Hash</h3><div class="log-viewer">${NESS.escape(e.hash_value)}</div><h3>Raw Evidence Record</h3><div class="log-viewer">${NESS.escape(e.raw_data)}</div></div></section><aside class="panel"><div class="panel-header"><div class="panel-title">Chain of Custody</div></div><div class="panel-body"><div class="health-row"><span>Captured by</span><strong>NESS Engine</strong></div><div class="health-row"><span>Storage status</span><strong>Preserved</strong></div><div class="health-row"><span>Incident</span><strong>${NESS.escape(e.incident_code)}</strong></div><button class="button button-primary button-block" onclick="navigator.clipboard?.writeText('${NESS.escape(e.hash_value)}');NESS.toast('Hash copied','success')">Copy Hash</button></div></aside></div>`; }catch(e){ main.innerHTML=`<section class="panel empty-state"><h2>Evidence not found</h2><p>${NESS.escape(e.message)}</p></section>`; } },
  async renderReportPreview(){ const id=this.params().get('id')||'latest'; const main=document.querySelector('main.page'); if(!main) return; try{ const d=await this.get(`/api/reports/${encodeURIComponent(id)}`); const r=d.report,i=d.incident,ev=d.evidence||[],an=d.analysis,h=d.history||[]; main.innerHTML=`<section class="page-header"><div><div class="breadcrumb">NESS Platform / Reports / ${NESS.escape(r.report_code)}</div><h1>Report Preview</h1></div><div class="page-header-actions"><button class="button button-primary" onclick="NESS_API.downloadReport(${r.id})">Download PDF</button><button class="button button-secondary" onclick="window.print()">Print</button></div></section><section class="report-document"><div class="report-title"><div><h2>NESS Incident Investigation Report</h2><p style="color:var(--muted);margin:6px 0 0">Report ID: ${NESS.escape(r.report_code)} • Prepared: ${NESS.escape(r.generated_at)}</p></div><div class="brand-mark"><i class="fa-solid fa-shield-halved"></i></div></div><div class="summary-list"><div><span>Incident</span><strong>${NESS.escape(i.incident_code)}</strong></div><div><span>Severity</span><strong style="color:var(--danger)">${NESS.escape(i.severity)}</strong></div><div><span>Type</span><strong>${NESS.escape(i.attack_type)}</strong></div><div><span>Status</span><strong>${NESS.escape(i.status)}</strong></div></div><h3>Executive Summary</h3><p>NESS detected and documented this incident through the live detection workflow. The record includes request evidence, alert delivery data, incident status history, and defensive analysis.</p><h3>Incident Data</h3><table class="table"><tbody><tr><th>Source IP</th><td>${NESS.escape(i.source_ip)}</td></tr><tr><th>Location</th><td>${NESS.escape((i.source_country||'')+' '+(i.source_city||''))}</td></tr><tr><th>Target</th><td>${NESS.escape(i.target||'')}</td></tr><tr><th>Path</th><td>${NESS.escape(i.path||'')}</td></tr><tr><th>Payload</th><td><code>${NESS.escape(i.payload||i.query_string||'')}</code></td></tr></tbody></table><h3>Evidence Summary</h3><table class="table"><thead><tr><th>Evidence ID</th><th>Type</th><th>Hash</th><th>Captured</th></tr></thead><tbody>${ev.map(e=>`<tr><td>${NESS.escape(e.evidence_code)}</td><td>${NESS.escape(e.evidence_type)}</td><td><code>${NESS.escape(e.hash_value.slice(0,20))}</code></td><td>${NESS.escape(e.captured_at)}</td></tr>`).join('')||'<tr><td colspan="4">No evidence records.</td></tr>'}</tbody></table><h3>AI Analysis</h3>${an?`<p>${NESS.escape(an.analysis_summary)}</p><pre class="log-viewer">${NESS.escape(an.recommendations)}</pre>`:'<p>No AI analysis has been generated for this incident.</p>'}<h3>Status History</h3><ul>${h.map(x=>`<li>${NESS.escape(x.changed_at)} — ${NESS.escape(x.old_status||'-')} → ${NESS.escape(x.new_status)} — ${NESS.escape(x.remarks||'')}</li>`).join('')||'<li>No history records.</li>'}</ul></section>`; }catch(e){ main.innerHTML=`<section class="panel empty-state"><h2>No report found</h2><p>Generate a report first from the Reports page.</p></section>`; } },
  async renderAiPage(){ const main=document.querySelector('main.page'); if(!main) return; let engine={}; try{engine=(await this.get('/api/realtime/status')).engine||{};}catch(_){engine={};} const latest=(window.NESS_DATA.analysisHistory||[])[0]; const running=!!engine.started; const latestHtml=latest?`<div class="card" style="background:#f0f9ff;border-color:#bae6fd"><h3 style="margin-top:0">Latest Automatic AI Result</h3><p>${NESS.escape(latest.summary||latest.result||'')}</p><div class="grid grid-4"><div><div class="metric-label">Classification</div><strong>${NESS.escape(latest.classification)}</strong></div><div><div class="metric-label">Risk Score</div><strong>${NESS.escape(latest.riskScore)}/100</strong></div><div><div class="metric-label">Predicted Priority</div><strong>${NESS.escape(latest.predictedSeverity)}</strong></div><div><div class="metric-label">Threat Likelihood</div><strong>${NESS.escape(latest.threatProbability)}</strong></div></div><h4>Prediction</h4><p>${NESS.escape(latest.prediction||'')}</p><h4>Recommendations</h4><pre class="log-viewer">${NESS.escape(latest.recommendations||'')}</pre></div>`:'<div class="card"><strong>Waiting for the first detected incident.</strong><p>NESS will analyze it automatically as soon as the detector creates the incident.</p></div>'; main.innerHTML=`<section class="page-header"><div><div class="breadcrumb">NESS Platform / AI Analysis</div><h1>Real-Time Automatic AI Analysis</h1></div><div class="page-header-actions"><span class="badge ${running?'badge-active':'badge-danger'}">${running?'Automation Running':'Automation Stopped'}</span></div></section><div class="grid grid-4" style="margin-bottom:18px"><div class="card metric-card"><div><div class="metric-label">Monitoring</div><div class="metric-value" style="font-size:22px">${engine.monitorAllHttpRequests?'Real-Time':'Watched Paths'}</div><div class="metric-note">Automatic request inspection</div></div></div><div class="card metric-card"><div><div class="metric-label">Automatic AI</div><div class="metric-value" style="font-size:22px">${engine.automaticAIEnabled?'Enabled':'Disabled'}</div><div class="metric-note">No manual incident analysis required</div></div></div><div class="card metric-card"><div><div class="metric-label">Processed</div><div class="metric-value">${NESS.escape(engine.aiProcessed||0)}</div><div class="metric-note">This server session</div></div></div><div class="card metric-card"><div><div class="metric-label">AI Queue</div><div class="metric-value">${NESS.escape(engine.queueSize||0)}</div><div class="metric-note">Pending real-time analyses</div></div></div></div><section class="panel" style="margin-bottom:18px"><div class="panel-header"><div><div class="panel-title">Automatic Pipeline</div><div class="panel-subtitle">Monitor → Detect → Preserve Evidence → Classify → Analyze → Risk Score → Predict → Alert → WebSocket/Arduino</div></div></div><div class="panel-body"><p style="margin:0">This page is now a live read-only analysis console. NESS performs classification, AI analysis, risk scoring, and prediction automatically for every detected incident.</p></div></section><section class="panel" style="margin-bottom:18px"><div class="panel-header"><div class="panel-title">Current AI Result</div></div><div class="panel-body">${latestHtml}</div></section><section class="panel"><div class="panel-header"><div><div class="panel-title">Automatic AI History</div><div class="panel-subtitle">Updates arrive over WebSocket without manual refresh</div></div></div><div class="table-wrap"><table class="table" id="aiHistoryTable"><thead><tr><th>Incident</th><th>Classification</th><th>Risk</th><th>Prediction</th><th>Model</th><th>Confidence</th><th>Time</th></tr></thead><tbody></tbody></table></div></section>`; NESS.renderDataTables(true); window.NESS_I18N?.apply(); },
  async renderGenerateReportPage(){ const main=document.querySelector('main.page'); if(!main) return; main.innerHTML=`<section class="page-header"><div><div class="breadcrumb">NESS Platform / Reports / Generate</div><h1>Generate Incident Report</h1></div></section><section class="panel"><div class="panel-header"><div><div class="panel-title">Report Configuration</div><div class="panel-subtitle">Create a PDF report from database records</div></div></div><div class="panel-body"><div class="field"><label>Select Incident</label><select id="reportIncidentSelect" class="select">${(window.NESS_DATA.incidents||[]).map(i=>`<option value="${i.dbId}">${NESS.escape(i.id)} — ${NESS.escape(i.type)} — ${NESS.escape(i.severity)}</option>`).join('')}</select></div><label><input type="checkbox" checked> Include digital evidence</label><br><label><input type="checkbox" checked> Include AI analysis</label><br><label><input type="checkbox" checked> Include status timeline</label><br><button class="button button-primary" style="margin-top:16px" onclick="NESS_API.generateReport()">Generate PDF Report</button></div></section>`; },
  async renderSettingsPage(){ const rows=window.NESS_SETTINGS||{}; document.querySelectorAll('input,select').forEach(el=>{ const label=el.closest('.field')?.querySelector('label')?.textContent?.trim(); const map={'System Name':'system_name','Default Role':'default_role','Live Transport':'polling_interval','Bot Token':'telegram_bot_token','SOC Chat ID':'telegram_chat_id','Port / Endpoint':'arduino_port','Alarm Policy':'arduino_policy','Model Name':'ollama_model','Confidence Threshold':'ai_confidence_threshold'}; const mapKey=Object.keys(map).find(k=>label===k || (window.NESS_I18N&&window.NESS_I18N.matches(label,k))); const key=map[mapKey]; if(key && rows[key]!==undefined) el.value=rows[key]; }); const bool=(v)=>String(v).toLowerCase()==='true'||String(v)==='1'||String(v).toLowerCase()==='yes'||String(v).toLowerCase()==='on'; const checks=[...document.querySelectorAll('input[type="checkbox"]')]; const keys=['monitoring_enabled','detect_sqli','detect_xss','detect_traversal','detect_rate','report_include_evidence','report_include_ai','telegram_enabled','arduino_enabled']; keys.forEach((key,idx)=>{ if(checks[idx] && rows[key]!==undefined) checks[idx].checked=bool(rows[key]); }); const setCheck=(id,key)=>{const el=document.getElementById(id);if(el&&rows[key]!==undefined)el.checked=bool(rows[key]);}; setCheck('monitorAllHttpRequests','monitor_all_http_requests');setCheck('autoAiEnabled','auto_ai_enabled');setCheck('autoLogAnalysisEnabled','auto_log_analysis_enabled'); const li=document.getElementById('autoLogInterval');if(li&&rows.auto_log_analysis_interval_seconds!==undefined)li.value=rows.auto_log_analysis_interval_seconds; setCheck('labEnabled','lab_enabled');setCheck('labAutoStart','lab_auto_start');const nr=document.getElementById('networkRetentionHours');if(nr&&rows.network_flow_retention_hours!==undefined)nr.value=rows.network_flow_retention_hours; },
  async renderRolesPermissionsPage(){ try{ const data=await this.get('/api/permissions'); const panel=document.querySelector('#rolesMatrixTable')?.closest('.panel'); if(!panel) return; let editor=document.getElementById('userPermissionEditor'); if(!editor){ panel.insertAdjacentHTML('beforeend', `<div class="panel-body" id="userPermissionEditor"><div class="field"><label>User Permission Overrides</label><select class="select" id="permissionUserSelect"></select></div><div id="permissionCheckboxes" class="grid grid-2" style="margin-top:12px"></div><div style="margin-top:16px"><button class="button button-primary" id="saveUserPermissionsBtn"><i class="fa-solid fa-save"></i> Save User Permissions</button> <button class="button button-secondary" id="resetUserPermissionsBtn">Use Role Defaults</button></div></div>`); editor=document.getElementById('userPermissionEditor'); } const select=document.getElementById('permissionUserSelect'); const box=document.getElementById('permissionCheckboxes'); if(!select||!box) return; select.innerHTML=(data.users||[]).map(u=>`<option value="${u.id}" data-role="${NESS.escape(u.role)}">${NESS.escape(u.name)} — ${NESS.escape(u.role)}</option>`).join(''); const renderChecks=()=>{ const user=(data.users||[]).find(u=>String(u.id)===String(select.value)); const custom=data.userPermissions?.[String(select.value)]; const defaults=data.roleDefaults?.[user?.role]||[]; const active=custom||defaults; const all=active.includes('*'); box.innerHTML=(data.permissions||[]).map(p=>`<label class="health-row"><span>${NESS.escape(p.label)}</span><input type="checkbox" data-permission-key="${NESS.escape(p.key)}" ${all||active.includes(p.key)?'checked':''}></label>`).join(''); }; select.addEventListener('change',renderChecks,{once:false}); renderChecks(); const pageSave=document.querySelector('body[data-page="roles-permissions.html"] .panel-header .button-primary'); const saveBtn=document.getElementById('saveUserPermissionsBtn'); const doSave=async(e)=>{ e.preventDefault(); e.stopPropagation(); const permissions=[...document.querySelectorAll('[data-permission-key]:checked')].map(x=>x.dataset.permissionKey); await this.post(`/api/permissions/users/${select.value}`,{permissions}); NESS.toast('User permissions saved','success'); await this.renderRolesPermissionsPage(); }; if(saveBtn&&!saveBtn.dataset.boundReal){ saveBtn.dataset.boundReal='1'; saveBtn.addEventListener('click',doSave); } if(pageSave&&!pageSave.dataset.boundReal){ pageSave.dataset.boundReal='1'; pageSave.addEventListener('click',doSave); } const resetBtn=document.getElementById('resetUserPermissionsBtn'); if(resetBtn&&!resetBtn.dataset.boundReal){ resetBtn.dataset.boundReal='1'; resetBtn.addEventListener('click',async e=>{ e.preventDefault(); e.stopPropagation(); await this.post(`/api/permissions/users/${select.value}/reset`,{}); NESS.toast('Permissions reset to role defaults','success'); await this.renderRolesPermissionsPage(); }); } }catch(e){ console.warn(e); NESS.toast(e.message,'danger'); } },

  async renderProfilePage(other=false){ const main=document.querySelector('main.page'); if(!main) return; try{ let d;if(other){ const id=this.params().get('id')||this.user?.id; d=await this.get(`/api/users/${id}`); } else d=await this.get('/api/profile'); const u=d.user; main.innerHTML=`<section class="page-header"><div><div class="breadcrumb">NESS Platform / Profile</div><h1>${NESS.escape(u.name)}</h1></div></section><div class="grid grid-main"><section class="panel"><div class="panel-header"><div><div class="panel-title">User Profile</div><div class="panel-subtitle">${NESS.escape(u.role)}</div></div>${window.NESS_DATA.roleBadge(u.role)}</div><div class="panel-body"><div class="grid grid-3"><div class="card"><div class="metric-label">Full Name</div><strong>${NESS.escape(u.name)}</strong></div><div class="card"><div class="metric-label">Email</div><strong>${NESS.escape(u.email)}</strong></div><div class="card"><div class="metric-label">Last Login</div><strong>${NESS.escape(u.last)}</strong></div></div>${other?'':`<div class="field" style="margin-top:18px"><label>Full Name</label><input id="profileName" class="input" value="${NESS.escape(u.name)}"></div><div class="field"><label>Email</label><input id="profileEmail" class="input" value="${NESS.escape(u.email)}"></div><div class="field"><label>Interface Language</label><select id="profileLanguage" class="select" data-language-select><option value="en">English</option><option value="ar">Arabic</option></select></div><button class="button button-primary" onclick="NESS_API.saveProfile()">Save Profile</button>`}</div></section><aside class="panel"><div class="panel-header"><div class="panel-title">Assigned Incidents</div></div><div class="panel-body">${(d.assignedIncidents||[]).map(i=>`<div class="health-row"><span>${NESS.escape(i.incident_code)}</span>${window.NESS_DATA.severityBadge(i.severity)}</div>`).join('')||'<p style="color:var(--muted)">No assigned incidents.</p>'}</div></aside></div>`; window.NESS_I18N?.apply(); }catch(e){console.warn(e)} },
  async renderAlertSummary(){
    if(document.body.dataset.page!=='alerts.html') return;
    try{ const [{summary},ard]=await Promise.all([this.get('/api/dashboard/summary'),this.get('/api/arduino/status').catch(()=>({arduino:{state:'Unavailable',message:'Status unavailable'}}))]); const t=document.getElementById('telegramAlertStatus'); if(t)t.textContent=summary.telegramStatus; const a=document.getElementById('arduinoAlertStatus'); if(a)a.textContent=ard.arduino?.state||summary.arduinoStatus; const an=document.getElementById('arduinoAlertNote');if(an)an.textContent=ard.arduino?.message||''; const tn=document.getElementById('telegramAlertNote');if(tn)tn.textContent=summary.telegramStatus==='Configured'?'Telegram delivery configured':'Configure Bot Token and Chat ID in Settings'; }catch(e){console.warn(e)}
  },
  async refreshCurrentView(reason='live-sync'){
    if(this.refreshBusy) return;
    this.refreshBusy=true;
    try{
      await this.loadUiData(true);
      await this.loadDashboardSummary();
      const page=document.body.dataset.page||'';
      if(page==='alerts.html') await this.renderAlertSummary();
      if(page==='ints-tracking.html') await this.loadIntsTracking();
      if(page==='logs.html') await this.loadLogAnalysisHistory();
      if(page==='ai-analysis.html') await this.renderAiPage();
      if(page==='network-devices.html') await this.loadNetworkDevicesPage();
      if(page==='network-traffic.html') await this.loadNetworkTrafficPage();
      if(page==='incident-details.html') await this.renderIncidentDetails();
      if(page==='evidence-details.html') await this.renderEvidenceDetails();
      try{ window.dispatchEvent(new CustomEvent('ness:dataChanged',{detail:{reason}})); }catch(_){}
    }catch(e){ console.warn('NESS live refresh failed',e); }
    finally{ this.refreshBusy=false; }
  },
  async checkUiRevision(force=false){
    if(document.hidden && !force) return;
    try{
      const data=await this.get('/api/ui-revision');
      const revision=data.revision||'';
      if(force || (this.lastUiRevision && revision!==this.lastUiRevision)){
        this.lastUiRevision=revision;
        await this.refreshCurrentView('revision-changed');
      }else if(!this.lastUiRevision){
        this.lastUiRevision=revision;
      }
    }catch(e){ console.warn('NESS revision check failed',e); }
  },
  startLiveDataSync(){
    if(!document.body.classList.contains('app-body') || this.liveSyncTimer) return;
    this.checkUiRevision(true);
    this.liveSyncTimer=setInterval(()=>this.checkUiRevision(false),1500);
    document.addEventListener('visibilitychange',()=>{ if(!document.hidden) this.checkUiRevision(true); });
    window.addEventListener('focus',()=>this.checkUiRevision(true));
  },
  startRealtimeAlerts(){
    if(!document.body.classList.contains('app-body') || this.liveSocket) return;
    const pauseBtn=document.getElementById('pauseLiveFeed');
    if(pauseBtn&&!pauseBtn.dataset.boundLivePause){ pauseBtn.dataset.boundLivePause='1'; pauseBtn.addEventListener('click',e=>{e.preventDefault();this.livePaused=!this.livePaused;pauseBtn.textContent=this.livePaused?'Resume feed':'Pause feed';NESS.toast(this.livePaused?'Live feed paused':'Live feed resumed','info');}); }
    const scheme=location.protocol==='https:'?'wss':'ws';
    const ws=new WebSocket(`${scheme}://${location.host}/ws/alerts`); this.liveSocket=ws;
    const state=(txt)=>{const el=document.getElementById('websocketAlertStatus');if(el)el.textContent=txt;};
    ws.onopen=()=>{state('Connected');};
    ws.onmessage=async evt=>{ let msg={}; try{msg=JSON.parse(evt.data||'{}')}catch(_){return;} try{window.dispatchEvent(new CustomEvent('ness:realtime',{detail:msg}))}catch(_){} if(msg.type==='ping'){try{ws.send('ping')}catch(_){}return;} if(this.livePaused)return; if(msg.type==='data.changed'){ this.refreshCurrentView('websocket-data-changed'); } if(msg.type==='alert.created'){NESS.toast(`New ${msg.payload?.severity||''} security alert`,'warning');} if(msg.type==='analysis.created'){NESS.toast(`Automatic AI completed: ${msg.payload?.classification||'incident classified'}`,'success');} try{await this.loadUiData(true);await this.loadDashboardSummary();if(document.body.dataset.page==='alerts.html')await this.renderAlertSummary();if(document.body.dataset.page==='ints-tracking.html')await this.loadIntsTracking();if(document.body.dataset.page==='logs.html')await this.loadLogAnalysisHistory();if(document.body.dataset.page==='ai-analysis.html' && ['analysis.created','analysis.queued','automation.started'].includes(msg.type))await this.renderAiPage();if(document.body.dataset.page==='incident-details.html' && ['incident.updated','analysis.created','report.created','alert.reviewed'].includes(msg.type))await this.renderIncidentDetails();if(document.body.dataset.page==='network-devices.html' && (msg.type.startsWith('network.')||msg.type.startsWith('lab.')))await this.loadNetworkDevicesPage();if(document.body.dataset.page==='network-traffic.html' && (msg.type.startsWith('network.')||msg.type.startsWith('lab.')))await this.loadNetworkTrafficPage();}catch(e){console.warn(e)} };
    ws.onclose=()=>{state('Reconnecting...');this.liveSocket=null;clearTimeout(this.liveReconnectTimer);this.liveReconnectTimer=setTimeout(()=>this.startRealtimeAlerts(),1500);};
    ws.onerror=()=>{state('Connection error');};
  },
  async loadSettings(){ if(document.body.dataset.page!=='settings.html') return; try{ const {settings}=await this.get('/api/settings'); window.NESS_SETTINGS=settings; await this.renderSettingsPage(); await this.refreshArduinoStatus(); }catch(e){} },
  bindLiveButtons(){ this.bindUsersPage(); this.bindTargetAdd(); const testArduino=document.querySelector('[data-action="test-arduino"]'); if(testArduino&&!testArduino.dataset.boundReal){testArduino.dataset.boundReal='1';testArduino.addEventListener('click',e=>{e.preventDefault();this.testArduino();});} const saveSettings=document.querySelector('[data-action="save-settings"]'); if(saveSettings && !saveSettings.dataset.boundReal){ saveSettings.dataset.boundReal='1'; saveSettings.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();this.saveSettings();}); } },
  async runAiAnalysis(){ const loading=document.getElementById('ai-loading'); const result=document.getElementById('ai-result'); const select=document.getElementById('aiIncidentSelect'); if(loading) loading.classList.remove('hidden'); if(result) result.classList.add('hidden'); try{ const data=await this.post('/api/ai/analyze',{incident_id:select?.value}); if(loading) loading.classList.add('hidden'); if(result){ result.classList.remove('hidden'); result.innerHTML=`<div class="card" style="background:#f0f9ff;border-color:#bae6fd"><h3 style="margin-top:0">AI Summary</h3><p>${NESS.escape(data.analysis.analysis_summary)}</p><div class="grid grid-3"><div><div class="metric-label">Confidence</div><strong>${(Number(data.analysis.confidence)*100).toFixed(1)}%</strong></div><div><div class="metric-label">Model</div><strong>${NESS.escape(data.analysis.model_name)}</strong></div><div><div class="metric-label">Source</div><strong>${NESS.escape(data.analysis.source)}</strong></div></div><h4>Recommendations</h4><pre class="log-viewer">${NESS.escape(data.analysis.recommendations)}</pre></div>`;} NESS.toast('Analysis saved in the database','success'); window.NESS_I18N?.apply(); await this.loadUiData(true); }catch(e){ if(loading) loading.classList.add('hidden'); NESS.toast(e.message,'danger'); } },
  async generateReport(){ try{ const select=document.getElementById('reportIncidentSelect'); const data=await this.post('/api/reports/generate',{incident_id:select?.value}); NESS.toast('PDF report generated','success'); await this.loadUiData(true); setTimeout(()=>location.href=`report-preview.html?id=${data.report.id}`,500); }catch(e){ NESS.toast(e.message,'danger'); } },
  downloadReport(id){ if(!id){NESS.toast('Report ID not found','danger');return;} location.href=`/reports/download/${id}`; },
  async quickStatus(id,status){ try{ await this.post(`/api/incidents/${id}/status`,{status,remarks:`Status changed to ${status} from console`}); NESS.toast('Incident status updated','success'); await this.loadEverything(true); }catch(e){ NESS.toast(e.message,'danger'); } },
  async saveIncidentNotes(id){ try{ await this.post(`/api/incidents/${id}/notes`,{notes:document.getElementById('incidentNotes')?.value||''}); NESS.toast('Notes saved','success'); }catch(e){ NESS.toast(e.message,'danger'); } },
  async assignIncident(id){ const user_id=document.getElementById('incidentAssignee')?.value; try{ await this.post(`/api/incidents/${id}/assign`,{user_id}); NESS.toast('Incident assigned','success'); await this.renderIncidentDetails(); }catch(e){ NESS.toast(e.message,'danger'); } },
  openAssignIncident(id){ const user=(window.NESS_DATA.users||[])[0]; if(!user){ NESS.toast('No active users available','warning'); return; } this.post(`/api/incidents/${id}/assign`,{user_id:user.id}).then(()=>{NESS.toast('Incident assigned','success'); return this.loadUiData(true);}).catch(e=>NESS.toast(e.message,'danger')); },
  async reviewAlert(id){ try{ await this.post(`/api/alerts/${id}/review`,{}); NESS.toast('Alert marked as reviewed','success'); await this.loadEverything(true); }catch(e){ NESS.toast(e.message,'danger'); } },
  async openEditUser(id){ try{ const d=await this.get(`/api/users/${id}`); const u=d.user; let modal=document.getElementById('editUserModal'); if(!modal) return; modal.dataset.userId=id; const inputs=modal.querySelectorAll('input'); const selects=modal.querySelectorAll('select'); if(inputs[0]) inputs[0].value=u.name||''; if(inputs[1]) inputs[1].value=u.email||''; if(inputs[2]) inputs[2].value=u.username||''; if(inputs[3]) inputs[3].value=''; if(selects[0]) selects[0].value=u.role; if(selects[1]) selects[1].value=u.status==='Inactive'?'Inactive':'Active'; modal.classList.add('open'); const update=modal.querySelector('.button-primary'); if(update && !update.dataset.boundReal){ update.dataset.boundReal='1'; update.addEventListener('click',async e=>{ e.preventDefault(); e.stopPropagation(); const uid=modal.dataset.userId; const inp=modal.querySelectorAll('input'); const ss=modal.querySelectorAll('select'); const payload={name:inp[0]?.value,email:inp[1]?.value,username:inp[2]?.value,role:ss[0]?.value,status:ss[1]?.value}; if(inp[3]?.value) payload.password=inp[3].value; try{ await this.put(`/api/users/${uid}`,payload); modal.classList.remove('open'); NESS.toast('User updated','success'); await this.loadUiData(true); }catch(err){ NESS.toast(err.message,'danger'); } }); } }catch(e){ NESS.toast(e.message,'danger'); } },
  async toggleUserStatus(id,status){ try{ await this.post(`/api/users/${id}/status`,{status}); NESS.toast(`User ${status}`,'success'); await this.loadUiData(true); }catch(e){ NESS.toast(e.message,'danger'); } },
  async saveProfile(){ try{ await this.put('/api/profile',{name:document.getElementById('profileName')?.value,email:document.getElementById('profileEmail')?.value}); NESS.toast('Profile updated','success'); await this.loadCurrentUser(); }catch(e){ NESS.toast(e.message,'danger'); } },
  async refreshArduinoStatus(){ if(document.body.dataset.page!=='settings.html')return; try{const r=await this.get('/api/arduino/status');const b=document.getElementById('arduinoConnectionBadge');if(b){b.textContent=r.arduino.state;b.className='badge '+(r.arduino.connected?'badge-active':'badge-warning');b.title=r.arduino.message||'';}}catch(e){const b=document.getElementById('arduinoConnectionBadge');if(b)b.textContent='Unavailable';} },
  async testArduino(){ try{const r=await this.post('/api/arduino/test',{});NESS.toast(`Arduino: ${r.arduino?.message||'Alarm triggered'}`,'success');await this.refreshArduinoStatus();}catch(e){NESS.toast(e.message,'warning');await this.refreshArduinoStatus();} },
  async loadIntsTracking(){ if(document.body.dataset.page!=='ints-tracking.html')return; const q=document.getElementById('intsSearch')?.value||'';const status=document.getElementById('intsStatus')?.value||'';try{const r=await this.get(`/api/ints?q=${encodeURIComponent(q)}&status=${encodeURIComponent(status)}`);const tb=document.querySelector('#intsTable tbody');if(tb)tb.innerHTML=(r.tracking||[]).map(x=>window.NESS_DATA.intsRow(x)).join('')||'<tr><td colspan="8" style="text-align:center;padding:24px">No INTS records found.</td></tr>';}catch(e){NESS.toast(e.message,'danger')} },
  async runLogAnalysis(){ const result=document.getElementById('logAnalysisResult');if(result)result.innerHTML='<p>Analyzing database logs...</p>';try{const r=await this.post('/api/log-analysis',{hours:Number(document.getElementById('logAnalysisHours')?.value||24),category:document.getElementById('logAnalysisCategory')?.value||'',level:document.getElementById('logAnalysisLevel')?.value||''});this.renderLogAnalysis(r.analysis);NESS.toast('Security log analysis saved','success');await this.loadLogAnalysisHistory();}catch(e){if(result)result.innerHTML=`<div class="card"><strong>Analysis failed:</strong> ${NESS.escape(e.message)}</div>`;} },
  renderLogAnalysis(a){ const result=document.getElementById('logAnalysisResult');if(!result||!a)return;const findings=Array.isArray(a.findings)?a.findings:[];result.innerHTML=`<div class="card"><div class="grid grid-3"><div><div class="metric-label">Analysis ID</div><strong>${NESS.escape(a.analysis_code)}</strong></div><div><div class="metric-label">Logs Analyzed</div><strong>${NESS.escape(a.log_count)}</strong></div><div><div class="metric-label">Risk Score</div><strong>${NESS.escape(a.risk_score)}/100</strong></div></div><p>${NESS.escape(a.summary)}</p><h4>Findings</h4><ul>${findings.map(x=>`<li>${NESS.escape(x)}</li>`).join('')}</ul><h4>Recommendations</h4><pre class="log-viewer">${NESS.escape(a.recommendations||'')}</pre></div>`; },
  async loadLogAnalysisHistory(){ if(document.body.dataset.page!=='logs.html')return;try{const r=await this.get('/api/log-analysis');const box=document.getElementById('logAnalysisHistory');if(box){box.innerHTML=(r.analyses||[]).slice(0,8).map(a=>`<div class="timeline-item"><strong>${NESS.escape(a.analysis_code)} • Risk ${NESS.escape(a.risk_score)}/100</strong><p>${NESS.escape(a.generated_at)} • ${NESS.escape(a.log_count)} logs • ${NESS.escape(a.generated_by_name||'NESS')}</p><button class="button button-secondary button-small" onclick='NESS_API.renderLogAnalysis(${JSON.stringify(a).replace(/'/g,"&#39;")})'>View</button></div>`).join('')||'<p style="color:var(--muted)">No saved analyses yet.</p>';}}catch(e){console.warn(e)} },
  formatBytes(value){const n=Number(value||0);if(n<1024)return `${n} B`;if(n<1024*1024)return `${(n/1024).toFixed(1)} KB`;if(n<1024*1024*1024)return `${(n/(1024*1024)).toFixed(1)} MB`;return `${(n/(1024*1024*1024)).toFixed(2)} GB`;},
  async loadNetworkDevicesPage(){ if(document.body.dataset.page!=='network-devices.html')return; try{const [r,d]=await Promise.all([this.get('/api/lab/status'),this.get('/api/network/devices')]);const n=r.lab||{};window.NESS_DATA.networkDevices=d.devices||[];NESS.renderDataTables(true);const online=(d.devices||[]).filter(x=>x.status==='Online').length;const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v??'—';};set('networkOnlineDevices',online);set('networkSensorState',n.sensorState||'Unknown');set('networkSensorMessage',n.sensorMessage||n.lastError||'');set('networkInterface',n.mode||'Integrated Virtual Fabric');set('networkCidr','Users 10.10.10 • DMZ 10.10.20 • Data 10.10.30');}catch(e){console.warn(e)} },
  async loadNetworkTrafficPage(){ if(document.body.dataset.page!=='network-traffic.html')return; try{const protocol=document.getElementById('networkProtocolFilter')?.value||'';const [status,summary,traffic]=await Promise.all([this.get('/api/lab/status'),this.get('/api/network/traffic/summary'),this.get(`/api/network/traffic?limit=300&protocol=${encodeURIComponent(protocol)}`)]);window.NESS_DATA.networkFlows=traffic.flows||[];NESS.renderDataTables(true);const n=status.lab||{},s=summary.summary||{};const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v??'—';};set('netFlows24h',s.flows||0);set('netPackets24h',s.packets||0);set('netBytes24h',this.formatBytes(s.bytes||0));set('netThreatFlows',s.suspiciousFlows||0);set('netTrafficInterface',n.resolvedInterface||'NESS Gateway');set('netTrafficCidr',n.resolvedCidr||'10.10.x.x segmented lab');set('netLastPacket',n.lastPacketAt||'—');set('netSensorScope',n.sensorMessage||n.captureScope||'');const b=document.getElementById('netSensorBadge');if(b){b.textContent=n.sensorState||'Unknown';b.className='badge '+(n.sensorState==='Running'?'badge-active':n.sensorState==='Degraded'||n.sensorState==='Setup Required'?'badge-warning':'badge-muted');}}catch(e){console.warn(e)} },
  async refreshCyberRange(){try{await this.loadUiData(true);if(document.body.dataset.page==='network-devices.html')await this.loadNetworkDevicesPage();if(document.body.dataset.page==='network-traffic.html')await this.loadNetworkTrafficPage();NESS.toast('Cyber range data refreshed','success');}catch(e){NESS.toast(e.message,'danger');}},
  async discoverNetworkNow(){return this.refreshCyberRange();},
  async restartNetworkSensor(){try{const r=await this.post('/api/lab/reset',{});NESS.toast(`Cyber range: ${r.lab?.sensorState||'reset'}`,r.lab?.sensorState==='Running'?'success':'warning');await this.refreshCyberRange();}catch(e){NESS.toast(e.message,'danger');}},
  async saveSettings(){ const fields=[...document.querySelectorAll('input,select')]; const find=(label)=>{const f=fields.find(el=>{const txt=el.closest('.field')?.querySelector('label')?.textContent?.trim()||''; return txt===label || (window.NESS_I18N&&window.NESS_I18N.matches(txt,label));});return f?f.value:''}; const checks=[...document.querySelectorAll('input[type="checkbox"]')]; const data={system_name:find('System Name'),default_role:find('Default Role'),polling_interval:find('Live Transport')||'WebSocket',telegram_bot_token:find('Bot Token'),telegram_chat_id:find('SOC Chat ID'),arduino_port:find('Port / Endpoint'),arduino_policy:find('Alarm Policy'),ollama_model:find('Model Name'),ai_confidence_threshold:find('Confidence Threshold'),monitoring_enabled:String(checks[0]?.checked||false),detect_sqli:String(checks[1]?.checked||false),detect_xss:String(checks[2]?.checked||false),detect_traversal:String(checks[3]?.checked||false),detect_rate:String(checks[4]?.checked||false),report_include_evidence:String(checks[5]?.checked||false),report_include_ai:String(checks[6]?.checked||false),telegram_enabled:String(checks[7]?.checked||false),arduino_enabled:String(checks[8]?.checked||false),monitor_all_http_requests:String(document.getElementById('monitorAllHttpRequests')?.checked??true),auto_ai_enabled:String(document.getElementById('autoAiEnabled')?.checked??true),auto_log_analysis_enabled:String(document.getElementById('autoLogAnalysisEnabled')?.checked??true),auto_log_analysis_interval_seconds:String(document.getElementById('autoLogInterval')?.value||60),lab_enabled:String(document.getElementById('labEnabled')?.checked??true),lab_auto_start:String(document.getElementById('labAutoStart')?.checked??true),network_flow_retention_hours:String(document.getElementById('networkRetentionHours')?.value||24)}; try{ await this.post('/api/settings',data); NESS.toast('Settings saved in database','success'); await this.refreshArduinoStatus(); }catch(e){ NESS.toast(e.message,'danger'); } }
};
document.addEventListener('DOMContentLoaded',()=>NESS_API.boot());
